const D=window.DATAPILOT_DATA;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const money=n=>`A₭ ${Number(n).toLocaleString('en-US')}`;
let currentScenario=D.scenarios[0],resourceTab='dashboards',weeklyTab='gmv';

function setView(view){
  $$('.view').forEach(v=>v.classList.toggle('active',v.id===`${view}View`));
  $$('.primary-tab').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
  window.scrollTo({top:0,behavior:'smooth'});
}
function bilingual(c,e){return `${c}<small>${e}</small>`}
function summary(items){return `<section class="ai-summary"><div class="summary-head"><span>✦</span><div><strong>智能总结与诊断</strong><small>AI Summary & Diagnosis</small></div></div><div class="summary-grid">${items.map(x=>`<div class="summary-item"><b>${x[0]}</b><p>${x[1]}</p></div>`).join('')}</div></section>`}
function titleBlock(s){return `<div class="result-title"><div><h2>${s.title}</h2><small>${s.en}</small></div><span>更新至 2026-10-04 · T-2</span></div>`}
function kpis(cards){return `<section class="kpi-grid">${cards.map(c=>`<article class="kpi-card"><label>${c[0]}<small>${c[1]}</small></label><strong class="${c[4]||''}">${c[2]}</strong><em>${c[3]}</em></article>`).join('')}</section>`}
function filterRow(primary=['季度','月度','近7日']){return `<div class="filter-row"><div class="filter-left"><span class="filter-label">时间范围 · TIME RANGE</span>${primary.map((x,i)=>`<button class="filter-chip ${i===0?'active':''}">${x}</button>`).join('')}</div><div class="filter-right"><button class="filter-chip active">全部类型</button><button class="filter-chip">导出表格</button></div></div>`}
function wide(title,en,heads,rows,cls=''){return `<section class="wide-section"><div class="wide-head"><h3>${title}<small>${en}</small></h3><span>左右滑动查看完整明细 · Swipe horizontally</span></div><div class="table-scroll"><table class="data-table ${cls}"><thead><tr>${heads.map(h=>`<th>${Array.isArray(h)?bilingual(h[0],h[1]):h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div></section>`}
function bindFilters(){
  $$('.filter-chip').forEach(b=>b.onclick=()=>{const group=b.parentElement;group.querySelectorAll('.filter-chip').forEach(x=>x.classList.remove('active'));b.classList.add('active')});
}

