function renderResult(s){
  window.dispatchEvent(new Event('datapilot:legacy-result'));$('#resultMount').classList.remove('hidden');
  currentScenario=s;$('#queryInput').value=s.query;$$('.quick-card').forEach(c=>c.classList.toggle('active',c.dataset.scenario===s.id));$('#stageEmpty').classList.add('hidden');const mount=$('#resultMount');mount.innerHTML='<div class="stage-empty"><span>✦</span><strong>DataPilot 正在分析</strong><small>Analyzing the selected workflow...</small></div>';setTimeout(()=>{const fn={budget:renderBudget,gmv:renderGMV,hunting:renderHunting,weekly:renderWeekly,seller:renderSeller,category:renderCategory}[s.type];mount.innerHTML=`<div class="result-shell">${fn(s)}</div>`;bindFilters();bindWeekly();$('#analysisStage').scrollIntoView({behavior:'smooth',block:'start'})},420)
}
function bindWeekly(){$$('[data-weekly]').forEach(b=>b.onclick=()=>{weeklyTab=b.dataset.weekly;$$('[data-weekly]').forEach(x=>x.classList.toggle('active',x===b));$('#weeklyTableMount').innerHTML=weeklyTable()})}
function renderUnsupported(q){currentScenario=null;$$('.quick-card').forEach(c=>c.classList.remove('active'));$('#stageEmpty').classList.add('hidden');$('#resultMount').innerHTML=`<div class="result-shell"><section class="scope-message"><span class="scope-icon">?</span><div><p class="scope-kicker">能力边界 · SCOPE CHECK</p><h2>这个问题不在 DataPilot 的数据分析范围内</h2><small>“${q.replace(/[<>]/g,'')}” 未匹配到预算、成交额、选品、周报、店铺或类目分析能力。</small><p>我不会为了生成结果而强行套用某个分析模板。请选择下方支持的问题，或换一种包含业务对象和分析目标的问法。</p></div></section><div class="scope-options">${D.scenarios.map(s=>`<button data-scope-scenario="${s.id}"><b>${s.title}</b><small>${s.en}</small></button>`).join('')}</div></div>`;$$('[data-scope-scenario]').forEach(b=>b.onclick=()=>renderResult(D.scenarios.find(s=>s.id===b.dataset.scopeScenario)));$('#analysisStage').scrollIntoView({behavior:'smooth',block:'start'})}
function detectIntent(q){const rules=[['budget',/(预算|补贴|预算单|消耗进度|budget|spend tracking)/i],['weekly',/(周报|周度复盘|经营复盘|weekly report)/i],['seller',/(单店|店铺|商家经营|seller\s*(performance|id)|shop\s*(performance|id|code))/i],['category',/(类目|品类|category\s*(performance|tracking|analysis))/i],['hunting',/(选品|商品清单|热销品|机会品|劣势品|hunting\s*list)/i],['gmv',/(gmv|成交额|分渠道|渠道追踪|okr|dagmv)/i]];return rules.find(([,pattern])=>pattern.test(q))?.[0]||null}
function runCustom(){const q=$('#queryInput').value.trim();if(!q)return;const intent=detectIntent(q);if(!intent){renderUnsupported(q);return}renderResult(D.scenarios.find(s=>s.id===intent))}

function dashboardCard(d){const tones={amber:['#FEF3C7','#92400E'],rose:['#FCE7F3','#9D174D'],violet:['#EDE9FE','#5B21B6'],green:['#DCFCE7','#166534'],blue:['#DBEAFE','#1D4ED8'],cyan:['#CFFAFE','#155E75']},t=tones[d.tone];return `<button class="dashboard-card" data-dashboard="${d.id}" style="--accent:${t[0]};--soft:${t[0]};--accentText:${t[1]}"><span class="dash-icon">↗</span><h3>${d.name}<small>${d.en}</small></h3><p>${d.desc}</p><b>打开完整演示看板 · Open preview →</b></button>`}
function renderResourceTab(tab){resourceTab=tab;$$('[data-resource-tab]').forEach(b=>b.classList.toggle('active',b.dataset.resourceTab===tab));const box=$('#resourceContent');if(tab==='dashboards'){const groups=['整体追踪','商家侧','达人侧','广告侧','策略侧'];box.innerHTML=`<div class="dashboard-groups">${groups.map(g=>{const items=D.dashboards.filter(d=>d.group===g);return `<section class="dashboard-group"><div class="group-title"><h2>${g}<small>${items[0]?.groupEn||''}</small></h2><span>${items.length} 个看板</span></div><div class="dashboard-grid">${items.map(dashboardCard).join('')}</div></section>`}).join('')}</div>`;$$('[data-dashboard]').forEach(b=>b.onclick=()=>openDashboard(b.dataset.dashboard));return}const rows=D.resources[tab],tags=['全部',...new Set(rows.map(r=>r.tag))];box.innerHTML=`<section class="resource-panel"><div class="resource-toolbar rich"><input class="resource-search" id="resourceSearch" placeholder="搜索名称、用途、标签或协作方…"><span class="resource-count">${rows.length} 项资源</span></div><div class="resource-tagbar">${tags.map((t,i)=>`<button class="resource-tag ${i===0?'active':''}" data-tag="${t}">${t}</button>`).join('')}</div><div class="table-scroll"><table class="resource-table rich-table"><thead><tr><th>标签</th><th>资源名称</th><th>用途</th><th>协作方</th><th>频率</th><th>格式</th><th>状态</th><th></th></tr></thead><tbody id="resourceRows">${resourceRows(rows)}</tbody></table></div></section>`;let tag='全部';const refresh=()=>{const q=$('#resourceSearch').value.toLowerCase();const filtered=rows.filter(r=>(tag==='全部'||r.tag===tag)&&[r.tag,r.name,r.en,r.owner,r.use].join(' ').toLowerCase().includes(q));$('#resourceRows').innerHTML=resourceRows(filtered);bindResourceButtons()};$('#resourceSearch').oninput=refresh;$$('.resource-tag').forEach(b=>b.onclick=()=>{tag=b.dataset.tag;$$('.resource-tag').forEach(x=>x.classList.toggle('active',x===b));refresh()});bindResourceButtons()}
function resourceRows(rows){return rows.map(r=>`<tr><td><span class="type-pill type-opportunity">${r.tag}</span></td><td><strong>${r.name}</strong><small>${r.en}</small></td><td class="resource-use">${r.use}</td><td>${r.owner}</td><td>${r.refresh}</td><td>${r.format}</td><td><span class="status-dot">●</span>${r.status}</td><td><button data-resource-demo="${r.name}">${r.action} →</button></td></tr>`).join('')}
function bindResourceButtons(){$$('[data-resource-demo]').forEach(b=>b.onclick=()=>openResourceDemo(b.dataset.resourceDemo))}
function pvHead(title,en,meta=''){return `<div class="pv-section-head"><div><h3>${title}</h3><small>${en}</small></div><span>${meta}</span></div>`}
function pvKpis(items){return `<div class="pv-kpis">${items.map(x=>`<article><label>${x[0]}<small>${x[1]}</small></label><strong class="${x[4]||''}">${x[2]}</strong><em>${x[3]}</em></article>`).join('')}</div>`}
function pvBars(values,labels=[],suffix=''){return `<div class="pv-bar-chart">${values.map((v,i)=>`<div><b>${v}${suffix}</b><i style="height:${Math.min(100,Math.max(8,v))}%"></i><small>${labels[i]||''}</small></div>`).join('')}</div>`}
function pvLine(a=[68,73,70,79,82,88,86,94,91,101,105,112],b=[61,64,69,72,78,75,83,86,90,92,96,99],suffix='K',xlabels=[]){const all=[...a,...b],min=Math.min(...all)*.88,max=Math.max(...all)*1.1,top=v=>10+(max-v)/(max-min)*60,pts=x=>x.map((v,i)=>`${i*100/(x.length-1)},${top(v)}`).join(' ');return `<div class="pv-line-chart"><div class="pv-y-axis"><span>${Math.round(max)}${suffix}</span><span>${Math.round((max+min)/2)}${suffix}</span><span>${Math.round(min)}${suffix}</span></div><svg viewBox="0 0 100 82" preserveAspectRatio="none"><line x1="0" y1="70" x2="100" y2="70"/><line x1="0" y1="40" x2="100" y2="40"/><line x1="0" y1="10" x2="100" y2="10"/><polyline class="line-a" points="${pts(a)}"/><polyline class="line-b" points="${pts(b)}"/></svg><div class="pv-point-labels">${a.map((v,i)=>`<span class="a" style="left:${i*100/(a.length-1)}%;top:${top(v)}%">${v}${suffix}</span>`).join('')}${b.map((v,i)=>`<span class="b" style="left:${i*100/(b.length-1)}%;top:${top(v)}%">${v}${suffix}</span>`).join('')}</div><div class="pv-x-axis">${a.map((_,i)=>`<span style="left:${i*100/(a.length-1)}%">${xlabels[i]||`D${i+1}`}</span>`).join('')}</div><div class="pv-legend"><span><i class="a"></i>实际 Actual</span><span><i class="b"></i>目标 Target</span></div></div>`}
function pvTable(heads,rows,wideClass=''){return `<div class="pv-table-wrap"><table class="pv-table ${wideClass}"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>`<td>${i===0?`<strong>${c}</strong>`:c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
