function filePreview(r){return `<div class="pv-file-meta"><span>${r.format.split(' ')[0]}</span><div><h3>${r.name}</h3><p>${r.en}</p></div><button>下载安全样例</button></div><div class="pv-tabs"><button class="active" data-pv-tab="outline" data-pv-group="file">文件结构</button><button data-pv-tab="preview" data-pv-group="file">内容预览</button><button data-pv-tab="history" data-pv-group="file">版本记录</button></div><section class="pv-section pv-tab-panel" data-pv-panel="outline" data-pv-group="file">${pvHead('文件结构','Document Structure',r.format)}<div class="pv-outline">${['01 · Overview / 使用说明','02 · Core Metrics / 核心指标','03 · Daily Detail / 分天明细','04 · Data Source / 数据来源','05 · Action Log / 行动记录'].map((x,i)=>`<button><b>${String(i+1).padStart(2,'0')}</b><span>${x}</span><em>${[1,18,126,6,12][i]} items</em></button>`).join('')}</div></section><section class="pv-section pv-tab-panel hidden" data-pv-panel="preview" data-pv-group="file">${pvHead('内容预览','Content Preview')}${pvTable(['模块','指标 / 字段','示例值','说明'],[['经营总览','Quarter GMV','A₭ 3.18M','季度累计'],['渠道追踪','Creator GMV','A₭ 1.46M','按归因渠道'],['商家层级','T4+ Sellers','17','周度快照'],['预算追踪','Budget Progress','68.4%','实际 / 目标']])}</section><section class="pv-section pv-tab-panel hidden" data-pv-panel="history" data-pv-group="file">${pvHead('版本记录','Version History')}<div class="pv-timeline"><p><b>v1.4 · 2026-10-04</b> 增加预算窗口与质量校验</p><p><b>v1.3 · 2026-09-20</b> 优化渠道层级和字段说明</p><p><b>v1.2 · 2026-08-31</b> 新增数据来源页</p></div></section>`}
function toolPreview(r){return `<section class="pv-section">${pvHead(r.name,r.en,r.status)}<div class="pv-tool-workspace"><aside><b>工作区 · Workspace</b>${['数据源','维度','指标','筛选器','排序与限制'].map((x,i)=>`<button class="${i===2?'active':''}">${x}<span>${[3,8,12,4,2][i]}</span></button>`).join('')}</aside><main><div class="pv-tool-top"><input value="DEMO_ANALYSIS_WORKSPACE"><button>运行 · Run</button></div><div class="pv-dropzone"><span>＋</span><strong>拖入指标或字段</strong><small>Drag dimensions and metrics here</small></div><div class="pv-config-grid"><label>维度<select><option>日期 Date</option></select></label><label>指标<select><option>成交额 GMV</option></select></label><label>聚合<select><option>SUM</option></select></label><label>限制<input value="1000"></label></div></main></div></section><section class="pv-section">${pvHead('输出预览','Output Preview','Interactive')}${pvBars([42,58,54,66,71,68,82,79,91,96],['1','','3','','5','','7','','9','10'])}</section>`}
function openResourceDemo(name){const all=Object.values(D.resources).flat(),r=all.find(x=>x.name===name),type=Object.entries(D.resources).find(([,v])=>v.includes(r))?.[0]||resourceTab;$('#dashboardModal').dataset.theme=type;$('#modalGroup').textContent=`${type==='queries'?'取数链接':type==='files'?'重要文件':'好用工具'} · RESOURCE PREVIEW`;$('#modalTitle').textContent=r.name;$('#modalEnglish').textContent=r.en;$('#modalBody').innerHTML=`<section class="dash-preview-hero"><div><span>${r.tag} · ${r.status}</span><h3>${r.name}</h3><p>${r.use}</p></div><span>${r.owner} · ${r.refresh}</span></section><div class="pv-resource-meta"><span>格式 <b>${r.format}</b></span><span>更新 <b>${r.refresh}</b></span><span>状态 <b>${r.status}</b></span><span>访问 <b>本地交互预览</b></span></div>${type==='queries'?queryPreview(r):type==='files'?filePreview(r):toolPreview(r)}`;openModal();bindPreviewInteractions()}
function dashPreview(id){return {overall:renderOverallDashboard,sellerBoard:renderSellerDashboard,creatorBoard:renderCreatorDashboard,pontos:renderPontosDashboard,budgetBoard:renderBudgetDashboard,pnl:renderPnlDashboard}[id]()}
function bindPreviewInteractions(){$$('[data-pv-filter]').forEach(b=>b.onclick=()=>{const p=b.parentElement;p.querySelectorAll('[data-pv-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active')});$$('[data-pv-tab]').forEach(b=>b.onclick=()=>{const g=b.dataset.pvGroup;$$(`[data-pv-tab][data-pv-group="${g}"]`).forEach(x=>x.classList.toggle('active',x===b));$$(`[data-pv-panel][data-pv-group="${g}"]`).forEach(x=>x.classList.toggle('hidden',x.dataset.pvPanel!==b.dataset.pvTab))});$$('.pv-table-search').forEach(inp=>inp.oninput=()=>{const q=inp.value.toLowerCase(),table=inp.parentElement.querySelector('table');table?.querySelectorAll('tbody tr').forEach(tr=>tr.style.display=tr.textContent.toLowerCase().includes(q)?'':'none')});$$('.pv-shop-select').forEach(s=>s.onchange=()=>{const label=s.parentElement.querySelector('.pv-shop-current');if(label)label.textContent=`当前选择：${s.value}`})}
function openDashboard(id){const d=D.dashboards.find(x=>x.id===id);$('#dashboardModal').dataset.theme=id;$('#modalGroup').textContent=`${d.group} · ${d.groupEn}`;$('#modalTitle').textContent=d.name;$('#modalEnglish').textContent=d.en;$('#modalBody').innerHTML=`<section class="dash-preview-hero"><div><span>${d.group} · ${d.groupEn}</span><h3>${d.name}</h3><p>${d.desc}</p></div><span>公开模拟看板 · Synthetic Preview</span></section><div class="pv-scroll-hint">↓ 向下滚动查看完整看板 · Scroll for full dashboard</div>${dashPreview(id)}`;openModal();$('#dashboardModal').scrollTop=0;bindPreviewInteractions()}
function openModal(){$('#dashboardModal').classList.add('open');$('#modalMask').classList.add('open');$('#dashboardModal').setAttribute('aria-hidden','false')}
function closeModal(){$('#dashboardModal').classList.remove('open');$('#modalMask').classList.remove('open');$('#dashboardModal').setAttribute('aria-hidden','true')}
const teamMessageKey='datapilot-public-team-messages-v1'
const teamMessageSeed=[
  {author:'Demo Analytics',type:'看板建议',text:'建议在整体经营日报中补充移动端快速查看入口。',date:'示例'},
  {author:'Demo Operations',type:'AI Skill',text:'已共享电商分析 Skill 示例包，欢迎补充更多诊断规则。',date:'示例'}
]
function safeText(value){return String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function getTeamMessages(){try{const saved=JSON.parse(localStorage.getItem(teamMessageKey)||'[]');return Array.isArray(saved)&&saved.length?saved:teamMessageSeed}catch{return teamMessageSeed}}
function renderTeamMessages(){const box=$('#teamMessages');if(!box)return;box.innerHTML=getTeamMessages().slice(0,6).map(item=>`<article><span>${safeText(item.author).slice(0,1).toUpperCase()}</span><div><div><strong>${safeText(item.author)}</strong><em>${safeText(item.type)} · ${safeText(item.date)}</em></div><p>${safeText(item.text)}</p></div></article>`).join('')}
function bindTeamSpace(){renderTeamMessages();const form=$('#teamMessageForm');if(!form)return;form.onsubmit=event=>{event.preventDefault();const author=$('#teamMemberName').value.trim()||'匿名共创者',type=$('#teamResourceType').value,text=$('#teamMessageText').value.trim();if(!text)return;const date=new Date().toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'});const messages=getTeamMessages();messages.unshift({author,type,text,date});localStorage.setItem(teamMessageKey,JSON.stringify(messages.slice(0,20)));$('#teamMessageText').value='';renderTeamMessages()}}
function renderDownloads(){$('#downloadGrid').innerHTML=D.downloads.map(f=>`<article class="download-card ${f.type==='SKILL'?'skill-download-card':''}">${f.type==='SKILL'?'<b class="public-package-badge">PUBLIC PACKAGE</b>':''}<span class="file-icon">${f.type}</span><h3>${f.name}<small>${f.en}</small></h3><p>${f.desc}</p><span>${f.meta}</span><a href="${f.file}" download>下载 ${f.type} · Download</a></article>`).join('')}
function init(){
  $('#promptGrid').innerHTML=D.scenarios.map(s=>`<button class="quick-card" data-scenario="${s.id}"><span class="quick-icon">${s.icon}</span><span><strong>${s.title}</strong><small>${s.en.toUpperCase()}</small></span></button>`).join('');
  $$('.primary-tab').forEach(b=>b.onclick=()=>setView(b.dataset.view));$$('[data-scenario]').forEach(b=>b.onclick=()=>{const s=D.scenarios.find(x=>x.id===b.dataset.scenario);if(s)window.dispatchEvent(new CustomEvent('datapilot:asset-question',{detail:{query:s.query,scenarioId:s.id,demo:true}}))});window.addEventListener('datapilot:run-scenario',e=>{const s=D.scenarios.find(x=>x.id===e.detail);if(s)window.dispatchEvent(new CustomEvent('datapilot:asset-question',{detail:{query:s.query,scenarioId:s.id,demo:true}}))});$$('[data-resource-tab]').forEach(b=>b.onclick=()=>renderResourceTab(b.dataset.resourceTab));$('#closeModal').onclick=closeModal;$('#modalMask').onclick=closeModal;renderResourceTab('dashboards');renderDownloads();bindTeamSpace()
}
export function initLegacy(){init()}
